export class Conn {
    constructor(port) {
        Object.defineProperty(this, "port", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "waiters", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "chunks", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        Object.defineProperty(this, "isClosed", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        this.isClosed = false;
        this.waiters = [];
        this.chunks = [];
        this.port = port;
        this.port.onmessage = (event) => {
            const chunk = new Uint8Array(event.data);
            this.chunks.push(chunk);
            if (this.waiters.length > 0) {
                const waiter = this.waiters.shift();
                if (waiter)
                    waiter();
            }
        };
    }
    read(p) {
        return new Promise((resolve) => {
            var tryRead = () => {
                if (this.isClosed) {
                    resolve(null);
                    return;
                }
                if (this.chunks.length === 0) {
                    this.waiters.push(tryRead);
                    return;
                }
                let written = 0;
                while (written < p.length) {
                    const chunk = this.chunks.shift();
                    if (chunk === null || chunk === undefined) {
                        resolve(written);
                        return;
                    }
                    const buf = chunk.slice(0, p.length - written);
                    p.set(buf, written);
                    written += buf.length;
                    if (chunk.length > buf.length) {
                        const restchunk = chunk.slice(buf.length);
                        this.chunks.unshift(restchunk);
                    }
                }
                resolve(written);
                return;
            };
            tryRead();
        });
    }
    write(p) {
        this.port.postMessage(p, [p.buffer]);
        return Promise.resolve(p.byteLength);
    }
    close() {
        if (this.isClosed)
            return;
        this.isClosed = true;
        this.waiters.forEach(waiter => waiter());
        this.port.close();
    }
}
